+/**
+ * @brief Incrementa ricorsivamente nshared su tutti i frame
+ *        del sottoalbero della zona cow (tabelle e pagine).
+ *
+ * @param tab_paddr	indirizzo fisico della tabella corrente
+ * @param begin		base dell'intervallo virtuale
+ * @param end		limite dell'intervallo virtuale
+ * @param lvl		livello corrente
+ */
+static void inc_nshared_subtree(paddr tab_paddr, vaddr begin, vaddr end, int lvl)
+{
+	natl i_first = i_tab(begin, lvl);
+	natl i_last = min(511, i_tab(end - 1, lvl));
+
+	for (natl i = i_first; i <= i_last; i++) {
+		tab_entry& e = get_entry(tab_paddr, i);
+		if (!(e & BIT_P))
+			continue;
+
+		paddr frame = extr_IND_FISICO(e);
+		vdf[frame / DIM_PAGINA].nshared++;
+
+		if (lvl > 1 && !(e & BIT_PS)) {
+			natq dr = dim_region(lvl - 1);
+			// Calcola il range virtuale di questa entrata
+			vaddr r_begin = base(begin, lvl - 1) + (i - i_first) * dr;
+			vaddr r_end = r_begin + dr;
+			vaddr sub_begin = max(begin, r_begin);
+			vaddr sub_end = min(end, r_end);
+			if (sub_begin < sub_end)
+				inc_nshared_subtree(frame, sub_begin, sub_end, lvl - 1);
+		}
+	}
+}
