+/**
+ * @brief Disfa le azioni di copia_cow() e aggiorna_cow() per il processo corrente.
+ *
+ * Funzione ricorsiva: processa le entrate di una tabella privata
+ * nel TRIE del processo corrente. Decrementa nshared per ogni frame
+ * (tabella o pagina) e lo dealloca solo se nessun altro processo lo condivide.
+ * Non modifica mai le entrate di tabelle condivise con altri processi.
+ *
+ * @param tab_paddr	indirizzo fisico della tabella (privata) da processare
+ * @param begin		base dell'intervallo virtuale
+ * @param end		limite dell'intervallo virtuale
+ * @param lvl		livello corrente nel TRIE
+ */
+static void distruggi_cow_rec(paddr tab_paddr, vaddr begin, vaddr end, int lvl)
+{
+	natl i_first = i_tab(begin, lvl);
+	natl i_last = min(511, i_tab(end - 1, lvl));
+
+	for (natl i = i_first; i <= i_last; i++) {
+		tab_entry& e = get_entry(tab_paddr, i);
+		if (!(e & BIT_P))
+			continue;
+
+		paddr frame = extr_IND_FISICO(e);
+		bool is_table = (lvl > 1 && !(e & BIT_PS));
+		natq frame_idx = frame / DIM_PAGINA;
+
+		// Determina se il frame va liberato:
+		// - se nshared > 0: decrementa e libera se diventa 0
+		// - se nshared == 0: solo questo processo lo ha, liberalo
+		bool need_free;
+		if (vdf[frame_idx].nshared > 0) {
+			vdf[frame_idx].nshared--;
+			need_free = (vdf[frame_idx].nshared == 0);
+		} else {
+			need_free = true;
+		}
+
+		if (need_free) {
+			if (is_table) {
+				// Tabella: processa ricorsivamente i
+				// sotto-livelli e poi libera la tabella
+				natq dr = dim_region(lvl - 1);
+				vaddr r_begin = base(begin, lvl - 1) + (i - i_first) * dr;
+				vaddr r_end = r_begin + dr;
+				vaddr sub_begin = max(begin, r_begin);
+				vaddr sub_end = min(end, r_end);
+				distruggi_cow_rec(frame, sub_begin, sub_end, lvl - 1);
+				rilascia_tab(frame);
+			} else {
+				// Pagina: liberala subito
+				rilascia_frame(frame);
+			}
+		}
+
+		// Cancella l'entrata nella tabella corrente (privata)
+		e = 0;
+		dec_ref(tab_paddr);
+	}
+}
+
 void distruggi_cow()
 {
-//// @todo Realizzare la funzione.
-// ( SOLUZIONE 2023-09-13
-//   SOLUZIONE 2023-09-13 )
+	// Percorre l'intera zona cow del processo corrente
+	distruggi_cow_rec(readCR3(), ini_utn_w, ini_utn_w + DIM_USR_COW, MAX_LIV);
 }
 //   ESAME 2023-09-13 )

